    assert.ok(readSelection({ ...MISMATCH, remainingMs }, GAME, []), 'remaining endpoint');
  const fraction = { ...MISMATCH, remainingMs: 1.5 };
  assert.equal(readSelection(fraction, GAME, []), null, 'fractional remaining time');
});

